-- TEST ONLY: contract snapshot from authorized fitness schema on 2026-10-14.
-- Never apply to Supabase. Disposable localhost PostgreSQL only.
create schema fitness;
create table fitness.users(id bigint generated always as identity primary key,telegram_user_id bigint unique not null,telegram_chat_id bigint,timezone text not null default 'Asia/Jakarta',is_active boolean not null default true,onboarding_completed boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table fitness.user_profiles(user_id bigint primary key references fitness.users(id) on delete cascade,birth_date date,sex_for_bmr text check(sex_for_bmr in ('male','female')),height_cm numeric check(height_cm between 50 and 250),current_weight_kg numeric check(current_weight_kg between 20 and 400),target_weight_kg numeric check(target_weight_kg between 20 and 400),activity_level text check(activity_level in ('sedentary','light','moderate','active','very_active')),updated_at timestamptz not null default now());
create table fitness.conversation_states(user_id bigint primary key references fitness.users(id) on delete cascade,payload jsonb not null,updated_at timestamptz not null default now());
create table fitness.bot_events(id bigint generated always as identity primary key,user_id bigint references fitness.users(id) on delete cascade,telegram_update_id bigint unique not null,event_type text not null,status text not null default 'received' check(status in ('received','processed','failed')),error_message text,created_at timestamptz not null default now());
create table fitness.nutrition_goals(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,daily_calories integer not null check(daily_calories between 800 and 10000),daily_protein_g numeric not null check(daily_protein_g between 0 and 500),daily_carbs_g numeric,daily_fat_g numeric,effective_from date not null,effective_to date check(effective_to>=effective_from),goal_mode text not null default 'maintenance' check(goal_mode in ('cutting','bulking','maintenance')),calorie_adjustment_pct numeric not null default 0 check(calorie_adjustment_pct between -30 and 25),estimated_maintenance_kcal integer check(estimated_maintenance_kcal between 800 and 10000),target_weekly_weight_change_pct numeric,calculation_method text not null default 'manual' check(calculation_method in ('manual','mifflin_st_jeor','other')),user_confirmed boolean not null default false);
create unique index on fitness.nutrition_goals(user_id) where effective_to is null;
create table fitness.body_weight_logs(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,measured_at timestamptz not null,weight_kg numeric not null check(weight_kg between 20 and 400),source text not null default 'telegram',created_at timestamptz not null default now());
create table fitness.food_logs(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,consumed_at timestamptz not null default now(),description text not null,calories integer not null check(calories between 0 and 10000),protein_g numeric not null default 0,carbs_g numeric not null default 0,fat_g numeric not null default 0,source text not null default 'manual',confirmed boolean not null default true);
create table fitness.workout_sessions(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,workout_at timestamptz not null default now(),title text not null,source text not null default 'manual',raw_text text not null,fingerprint text not null,unique(user_id,fingerprint));
create table fitness.workout_sets(id bigint generated always as identity primary key,session_id bigint not null references fitness.workout_sessions(id) on delete cascade,exercise_name text not null,set_number integer not null,weight_kg numeric,reps integer,raw_line text);
create table fitness.coach_reports(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,week_start date not null,report_text text not null,generated_at timestamptz not null default now(),unique(user_id,week_start));
create table fitness.reminder_settings(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,reminder_type text not null,enabled boolean not null default true,local_time time not null,day_of_week smallint check(day_of_week between 0 and 6),unique(user_id,reminder_type));
create table fitness.notification_deliveries(id bigint generated always as identity primary key,user_id bigint not null references fitness.users(id) on delete cascade,reminder_type text not null,scheduled_for timestamptz not null,delivered_at timestamptz,status text not null default 'pending' check(status in ('pending','sent','failed')),unique(user_id,reminder_type,scheduled_for));
